'use strict';
const $=id=>document.getElementById(id);
const warbands={
 ironsouls:{title:'Ironsoul’s Condemnors',prefix:'ironsouls-condemners',names:['Ironsoul','Tavian','Brodus']},
 velmorn:{title:'Sons of Velmorn',prefix:'sons-of-velmorn',names:['Morlak','Jedran','Thain','Helmar','Faulk']},
 krew:{title:'Da Kunnin’ Krew',prefix:'da-kunnin-krew',names:['Mannok','Torka','Krookgrin','Shank','Gikkit']},
 ephilim:{title:'Ephilim’s Pandaemonium',prefix:'ephilims-pandaemonium',names:['Ephilim','Spawnmaw','Flamespooler','Apo’trax','Kindlefinger']}
};
function initial(choices=['ironsouls','velmorn']){return {version:4,decks:[null,null],warbands:choices,players:['Hráč 1','Hráč 2'],active:1,started:false,fighters:[1,2].flatMap(player=>warbands[choices[player-1]].names.map((name,i)=>({name,player,id:(player-1)*10+i+1,card:i+1,warband:choices[player-1],x:280+i*330,y:player===1?1248:480,inspired:false,wounds:0}))),log:[],rolls:{attack:[],defence:[]}};}
let state;try{state=JSON.parse(localStorage.getItem('whu-online-v4'));if(!state||state.version!==4)throw Error();}catch{state=initial();}
let selected=1,opened=null,history=[],suppress=false;
const cardPath=(id,inspired=false)=>{if(id===0)return `assets/${warbands[state.warbands[state.active-1]].prefix}-0.png`;const f=state.fighters.find(f=>f.id===id);return `assets/${warbands[f.warband].prefix}-${f.card}${inspired?'-inspired':''}.png`;};
function save(){try{localStorage.setItem('whu-online-v4',JSON.stringify(state));}catch{}}
function before(){history.push(JSON.stringify(state));if(history.length>60)history.shift();}
function note(t){state.log.unshift(t);state.log=state.log.slice(0,80);}
const cells=[];
// Flat-top hexes: measured against the supplied board, in its original pixels.
for(let col=0;col<11;col++){let start=col%2?96:0;let top=[384,288,192,96,192,96,192,96,192,288,384][col];for(let y=top;y<=1730-top;y+=192){const x=115+col*165;cells.push({x,y});}}
$('grid').innerHTML=cells.map(c=>`<polygon points="${Array.from({length:6},(_,i)=>{let a=i*Math.PI/3;return `${c.x+110*Math.cos(a)},${c.y+110.8512516844*Math.sin(a)}`}).join(' ')}" data-x="${c.x}" data-y="${c.y}"/>`).join('');
function move(id,x,y){if(state.deployment?.complete&&!state.firstTurn?.confirmed)return;if(state.deployment&&!state.deployment.complete)return;if(state.treasures&&(!state.treasures.complete||state.treasures.aqua?.length!==2))return;if(state.fighters.find(f=>f.id===id).player!==state.active)return;const c=cells.reduce((a,b)=>Math.hypot(b.x-x,b.y-y)<Math.hypot(a.x-x,a.y-y)?b:a);const f=state.fighters.find(f=>f.id===id);if(f.x===c.x&&f.y===c.y)return;before();f.x=c.x;f.y=c.y;note(`${state.players[f.player-1]} · ${f.name}: přesun`);render();}
$('grid').onclick=e=>{if(e.target.dataset.x)move(selected,+e.target.dataset.x,+e.target.dataset.y);};
function show(id){opened=id;$('card').src=id===0?cardPath(0):cardPath(id,state.fighters.find(f=>f.id===id).inspired);$('viewer').showModal();}
$('close').onclick=()=>$('viewer').close();$('viewer').onclick=e=>{if(e.target===$('viewer'))$('viewer').close();};$('warscroll').onclick=()=>show(0);
function inspire(id){const f=state.fighters.find(f=>f.id===id);if(!f)return;before();f.inspired=!f.inspired;note(`${state.players[f.player-1]} · ${f.name}: ${f.inspired?'inspirován':'základní strana'}`);render();if(opened===id)$('card').src=cardPath(id,f.inspired);}

function render(){document.body.classList.toggle('playing',!!state.firstTurn?.confirmed);const chosen=state.decks[state.active-1];$('chosenDeckTitle').textContent=chosen?`Balíček · ${chosen.ids.length} karet`:'Balíček zatím nevybrán';$('chosenDeckCards').replaceChildren();if(chosen)for(const id of chosen.ids){const c=deckCatalog[id],b=document.createElement('button');b.type='button';b.className='deck-card';b.textContent=c?`${id} · ${c.name}`:id;b.disabled=!c;b.onclick=()=>previewDeckCard(id);$('chosenDeckCards').append(b);}if(!state.fighters.some(f=>f.id===selected&&f.player===state.active))selected=state.fighters.find(f=>f.player===state.active).id;save();$('warbandTitle').textContent=warbands[state.warbands[state.active-1]].title;$('player1').textContent=state.players[0];$('player2').textContent=state.players[1];for(const n of [1,2]){$('player'+n).setAttribute('aria-pressed',state.active===n);}$('activeLabel').textContent='Ovládáš: '+state.players[state.active-1];$('tokens').innerHTML=state.fighters.map(f=>`<button aria-label="${f.name}, přesunout; dvojklik otevře kartu" class="token player-${f.player} ${f.inspired?'inspired':''} ${selected===f.id?'selected':''}" data-id="${f.id}" style="left:${f.x/1887*100}%;top:${f.y/1730*100}%;background-image:url('${cardPath(f.id)}')"><span>${f.player} · ${f.name}</span>${f.wounds?`<b class="wounds">${f.wounds}</b>`:''}</button>`).join('');
 document.querySelectorAll('.token').forEach(el=>{el.ondblclick=()=>show(+el.dataset.id);el.onpointerdown=e=>{e.preventDefault();const clicked=+el.dataset.id;if(state.deployment&&!state.deployment.complete){show(clicked);return;}if(state.fighters.find(f=>f.id===clicked).player!==state.active){show(clicked);return;}selected=clicked;let startX=e.clientX,startY=e.clientY;el.setPointerCapture(e.pointerId);el.onpointermove=p=>{let r=$('board').getBoundingClientRect();const point=boardPoint(p.clientX,p.clientY);el.style.left=point.x/1887*100+'%';el.style.top=point.y/1730*100+'%';};el.onpointerup=p=>{el.onpointermove=null;const r=$('board').getBoundingClientRect();if(Math.hypot(p.clientX-startX,p.clientY-startY)>6)move(selected,boardPoint(p.clientX,p.clientY).x,boardPoint(p.clientX,p.clientY).y);else render();};el.onpointercancel=()=>render();};});
 renderWarbands();
 $('log').replaceChildren(...state.log.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));renderDice();if(typeof applyBoardOrientation==='function')applyBoardOrientation();if(typeof renderTreasures==='function')renderTreasures();if(typeof renderDeployment==='function')renderDeployment();if(typeof renderTurns==='function')renderTurns();if(typeof renderHandPlay==='function')renderHandPlay();}
const faces={attack:['💥','⚒','⚒','⚔','◐','●'],defence:['💥','🛡','🛡','↪','◐','●']};
const labels={'💥':'Kritický úspěch','⚒':'Kladivo','⚔':'Meče','◐':'Jedna podpora','●':'Dvě podpory','🛡':'Štít','↪':'Úhyb'};
function randomFace(type){const a=new Uint32Array(1);do{crypto.getRandomValues(a);}while(a[0]>=4294967292);return faces[type][a[0]%6];}
$('diceControls').innerHTML=['attack','defence'].map(type=>`<div class="dice-group"><label>${type==='attack'?'Útočné':'Obranné'} kostky</label><input id="count-${type}" aria-label="Počet kostek" type="number" min="1" max="20" value="3"><button id="roll-${type}">Hodit</button><div class="results" id="results-${type}"></div><button id="reroll-${type}">Přehodit vybrané</button></div>`).join('');
for(const type of ['attack','defence']){$('roll-'+type).onclick=()=>{const n=Math.max(1,Math.min(20,parseInt($('count-'+type).value)||1));before();state.rolls[type]=Array.from({length:n},()=>({face:randomFace(type),chosen:false}));note(`${type==='attack'?'Útok':'Obrana'}: ${state.rolls[type].map(d=>labels[d.face]).join(', ')}`);render();};$('reroll-'+type).onclick=()=>{if(!state.rolls[type].some(d=>d.chosen))return;before();state.rolls[type].forEach(d=>{if(d.chosen){d.face=randomFace(type);d.chosen=false;}});note(`Přehození (${type==='attack'?'útok':'obrana'}): ${state.rolls[type].map(d=>labels[d.face]).join(', ')}`);render();};}
function renderDice(){for(const type of ['attack','defence']){$('results-'+type).innerHTML=state.rolls[type].map((d,i)=>`<button class="die ${d.chosen?'chosen':''}" title="${labels[d.face]}" aria-label="${labels[d.face]}" aria-pressed="${d.chosen}" data-i="${i}">${diceFaceHTML(type,d.face)}</button>`).join('');$('results-'+type).querySelectorAll('button').forEach(b=>b.onclick=()=>{state.rolls[type][+b.dataset.i].chosen=!state.rolls[type][+b.dataset.i].chosen;save();renderDice();});}}
$('undo').onclick=()=>{if(history.length){state=JSON.parse(history.pop());render();}};$('reset').onclick=()=>{for(const n of [1,2]){$('name'+n).value=state.players[n-1];$('warband'+n).value=state.warbands[n-1];}updateSelection();prepareDeckForm(state.decks);$('setup').showModal();};
for(const n of [1,2])$('player'+n).onclick=()=>{if(state.combat)return;if(state.deployment&&!state.deployment.complete)return;state.active=n;selected=state.fighters.find(f=>f.player===n).id;render();};
$('setupForm').onsubmit=e=>{e.preventDefault();if(pendingDecks.some(d=>!d||d.unknown.length)){alert('Načti balíček obou hráčů. Před potvrzením musí být všechny kódy rozpoznané.');return;}let openingHands;try{openingHands=pendingDecks.map(d=>WHUHands.create(d,deckCatalog));}catch(error){alert(error.message);return;}if(state.started&&!confirm('Nahradit rozehranou partii novou?'))return;state=initial([$('warband1').value,$('warband2').value]);state.players=[$('name1').value.trim()||'Hráč 1',$('name2').value.trim()||'Hráč 2'];state.decks=JSON.parse(JSON.stringify(pendingDecks));state.started=true;state.hands=openingHands;history=[];selected=1;note('Sólo partie: '+state.warbands.map(k=>warbands[k].title).join(' proti ')+'. Pracovní stůl pro ověření výběru part.');$('setup').close();render();$('resumeHands').hidden=false;openStartingHands();};
$('cancelSetup').onclick=()=>{$('setup').close();};
$('setup').addEventListener('cancel',e=>{if(!state.started)e.preventDefault();});
render();if(!state.started)$('setup').showModal();

function updateSelection(){for(const n of [1,2]){const w=warbands[$('warband'+n).value];$('selection'+n).textContent=w.names.length+' bojovníků · '+w.names.join(', ');$('preview'+n).src=`assets/${w.prefix}-0.png`;}}
for(const n of [1,2])$('warband'+n).onchange=updateSelection;
updateSelection();

// Resume an unfinished hand preparation after reloading the page.
setTimeout(()=>{if(state.started&&state.hands){$('resumeHands').hidden=false;if(state.hands.some(h=>!h.confirmed))openStartingHands();}},0);

function diceFaceHTML(type,face){const clean=String(face).replace(/[\uFE0E\uFE0F]/g,'');const symbols=type==='attack'?['💥','⚒','⚔','◐','●']:['💥','🛡','↪','◐','●'];const index=symbols.indexOf(clean);if(index<0)return '<span style="font-size:12px;line-height:1.3">Neznámý výsledek</span>';const attack=type==='attack',picture=attack?"data:image/png;base64,":"data:image/png;base64,";const x=attack?[-31,-86,-141,-196,-251][index]:[-4,-59,-114,-169,-224][index];return `<span class="dice-picture" role="img" aria-label="${labels[clean]||clean}" style="display:inline-block;width:50px;height:50px;min-width:50px;border-radius:8px;background-image:url('${picture}');background-repeat:no-repeat;background-size:${attack?'312.5px 73px':'278.5px 63.5px'};background-position:${x}px ${attack?'-7.5':'-4'}px"></span>`;}
function showRollPicture(element,face){element.innerHTML=face?diceFaceHTML('attack',face)+'<span class="roll-face-label">'+labels[face]+'</span>':'Zatím neházeno';}
